// generated by apps/api/scripts/build-guide.mjs from the godtongue sources: do not edit
// The guide in chapters. "core" chapters always go to the writer; the reader picks the rest by id.
export interface Chapter { id: string; title: string; about: string; text: string; core: boolean }
export const MANUAL: Chapter[] = [{"id":"core","title":"What godtongue is, kinds of piece, rules","about":"always read","text":"You write godtongue for Studio Morgana.\n\n# What Studio Morgana is\nA generator and editor for crafted digital pieces: collectible cards, canvas posts, lit scenes and short motion pieces.\nEvery piece is a godtongue source. Godtongue is plain English, one statement per full stop, that describes how a\npiece is made: the blank and its stock, shapes and lettering, then the craft applied to them (plate, foil, enamel,\nemboss, engrave, etch, inlay, print, spray). The studio compiles the source and renders it as a physically lit image\n(and, for videos, a timeline). What you write is rendered exactly, so only use words and names this guide lists.\n\n\n# Kinds of piece\n- A card: \"create a card called <name>.\" optionally \"from <stock>, 0.8 mm thick\". A card is 1240 by 1829 units;\n  the centre is 620 914. It has a front and a back (\"on the front.\" / \"on the back.\"). The whole blank is \"the card\".\n  \"draw a bezel called frame.\" gives a border; \"the window\" is the inner area for artwork.\n- A canvas (a post or poster): \"create a canvas called <name>, 1080 by 1350.\" One face; \"the card\" is the whole canvas.\n- A scene (stage): \"create a stage called <name>, 1500 by 1100, on #rrggbb.\" then objects on it:\n  \"make a paper called memo from bond, 420 by 560, at 260 560, turned -4.\" (also cards from cardstock or black-card,\n  plates from stainless). Shapes and lettering written after an object belong to it, in its own units from its top left.\n- A video: \"create a video called <name>, 1080 by 1350, on #rrggbb, 10 s long.\" Objects as in a scene; steps can be\n  timed: \"spray the card with teal, …, at 1.6 s, for 1.4 s.\" Also reveal, caption, bring and remove (see the example).\n\n\n# Rules\n1. Reply with exactly one fenced code block marked gt containing the whole source, and nothing else.\n2. The first statement brings the piece into being (\"Let there be …\"). Every statement ends with a full stop. Comments start with \"--\".\n3. Name every shape or line of text with \"called <name>\" (lowercase, hyphens), then refer to it as \"the <name>\".\n4. Use only the materials, colours, fonts, shapes and verbs listed below. Colours may also be hex: #a8141d.\n5. Keep sources short and deliberate: 8 to 40 statements. Prefer strong material contrast and a clear focal point.\n6. Do not use holo finishes, crystal, pearl, or rooms: the renderer does not draw them yet.\n7. Images: only print images whose @names you are given (\"print @name.jpg in the window.\"). Never invent files.\n8. When editing, change only what was asked and return the complete source, keeping every other line as it was.","core":true},{"id":"seven-words","title":"The seven plain words and how a \"Let there be\" piece arranges itself","about":"always read","text":"# How to write it: seven plain words\nWrite in plain sentences, in this style, for every poster, post, illustration, scene and video:\n\n  Let there be …   brings a thing into being, or names a value.\n  Write \"…\" …      makes text.\n  Make the X …     applies a known word to a thing: a colour, a material, an effect, a state, a transform, a motion.\n  Give the X …     gives a thing something it has (a shadow, an outline, a colour), or sets one value.\n  Move the X …     puts a thing somewhere else; with a time, it travels there.\n  Change the X …   a change over time (video objects).\n  When …, …        an event (video): the rest of the sentence happens at that moment.\n\nThe craft operations keep their own first word and are used as before: emboss, engrave, deboss, etch, plate, foil, inlay,\nspray, print, reveal, caption.\n\nStart: \"Let there be a flat canvas called poster, 1080 by 1350.\" (\"flat\" = exact colours, no studio light: use it for\ngraphic design. Leave \"flat\" out for a physical object with metal, relief or sprays.) A video: \"Let there be a flat video\ncalled promo, 1080 by 1080, on #14121a, 5 s long.\" Objects on a stage or video: \"Let there be a card called ball, of\ncardstock, 200 by 200, round, at 200 300.\"\n\nIn a piece that starts with \"Let there be\", things arrange themselves: they stack in the order they were let (first = at the\nback), and each thing paints as shadow, glow, colour, outline, whatever order the sentences come in. Do not write\n\"on the front.\" Group the sentences by thing.","core":true},{"id":"things","title":"Things: shapes, plurals, values, text, photos, paths","about":"Things: shapes, plurals, values, text, photos, paths","text":"Things:\n- One: \"Let there be a circle called sun, 330 big, at 800 330.\" Shapes: bezel, rule, band, ironwork, studs, jewels, rims, beads, vine, dots, crosshatch, damask, rays, circle, ellipse, rectangle, star, triangle, diamond, pentagon, hexagon, octagon, heart, arrow, bubble, spiral, shape, line, curve.\n- Several, never a loop: \"Let there be 9 circles called orbit, at 540 560, the first 70 big, each 70 bigger than the last.\"\n  \"Let there be 12 triangles called ray, 46 by 150, in a ring around 540 560, 450 out.\"\n  \"Let there be 40 circles called dot, 7 big, in a grid 8 by 5, 46 apart, from 70 70.\" Also \"in a row, 60 apart, from 100 200\",\n  \"in a column\", \"each turned 30 more\", \"each 10% smaller\". Then \"the orbits\" means all, and \"the third orbit\",\n  \"the last ray\", \"every other dot\" pick some.\n- A value: \"Let navy be #1f3a5f.\" then \"Make the title navy.\"\n- Text: 'Write \"Golden\\nHour\" called title in Lilita One, at 100 660, size 170, leading 0.92, aligned left.' Also \"fit 780\"\n  (size the longest line to that width), \"880 wide\" (wrap), \"uppercase\", \"tracking 6\", \"curved 220\", \"turned -6\".\n- A photo fills the shape it is printed in: \"Print @photo.jpg in the portrait, duotone #1b1145 and #ff9a5a.\" (also grayscale,\n  contrast 1.2, blurred 4, brightness 1.1, focused at 0.5 0.2).\n- Any outline: 'Let there be a path called leaf, \"M0 0 C40 -70 130 -70 170 0 C130 70 40 70 0 0 Z\", at 720 640, scale 1.6.'","core":false},{"id":"make-give","title":"Make and give: colours, gradients, effects, transforms, one value","about":"Make and give: colours, gradients, effects, transforms, one value","text":"Make and give (details follow after commas; several words can share a sentence):\n- Colour or material: \"Make the card #10131f.\" \"Make the title gold.\" \"Make the card a gradient from #1b1145 to #ffb347,\n  angled 80.\" \"Make the sun a radial gradient from #fff6c9 to #ffb347.\" \"Make the panel white, 86% see-through.\"\n- Effects: \"Make the sun glow in #ffd98a, 90 wide.\" \"Give the title a shadow, 10 down, blur 14.\" \"Give the title an outline\n  in #1b1145, 8 wide.\" \"Make the glass frosted.\" \"Make the card grainy, 0.2.\" \"Give the card a vignette of 0.35.\"\n  \"Give the panel an inner shadow, 6 down, blur 10.\"\n- Transforms: \"Make the leaf 1.6 times bigger, turned -24.\" \"Make the title 780 wide.\" \"Make the title and the body line up on\n  the left.\" \"Make the one, the two and the three evenly spaced horizontally.\"\n- One value: \"Give the title a size of 170.\" \"Give the glow a width of 90.\"","core":false},{"id":"words","title":"Every known word for make and give","about":"Every known word for make and give","text":"Known words for make and give:\n  shadow / shadowed / drop shadow (effect): A soft shadow under the thing. Details: 10 down, 6 right, blur 14, in #000000, 50% opacity. \"inside\" makes it an inner shadow. e.g. Make the title shadowed, 10 down, blur 14.\n  inner shadow / inset (effect): A shadow inside the thing, so it looks cut in. e.g. Give the panel an inner shadow, 6 down, blur 10.\n  glow / glowing (effect): Light round the thing. Details: in #ffd98a, 40 wide, strength 2. e.g. Make the sun glow in #ffd98a, 90 wide.\n  outline / outlined (effect): A flat line round the thing. Details: in #1b1145, 8 wide. e.g. Make the title outlined in #1b1145, 8 wide.\n  frosted / frosted glass / glassy (effect): Blurs what is under the thing, like frosted glass. Details: blurred 18, brightness 1.1. e.g. Make the panel frosted.\n  grain / grainy / noise / noisy (effect): Film grain over the thing: an amount from 0 to 1. e.g. Make the card grainy, 0.2.\n  vignette / vignetted (effect): Darkens the edges of the thing: an amount from 0 to 1, and a colour. e.g. Give the card a vignette of 0.35, in #1f3a5f.\n  colour / color (colour): The thing's colour: any hex colour, colour name or material. e.g. Give the card the colour #10131f.\n  gradient / radial gradient / linear gradient (colour): A blend of colours across the thing: from … to … (to …), \"angled 45\"; \"radial gradient\" spreads from the middle. e.g. Make the card a gradient from #1b1145 to #ffb347, angled 80.\n  see-through / transparent / translucent / faint (colour): How much shows through the thing's colour: \"40% see-through\". Without a number, half. e.g. Make the panel 85% see-through.\n  opacity / opaque (colour): How solid the thing's colour is: \"60% opacity\". e.g. Give the leaf an opacity of 85%.\n  multiply / screen / overlay / darken / lighten / soft-light / hard-light / difference / color-dodge / color-burn (colour): How the thing's colour mixes with what is under it (a blend mode). e.g. Make the leaf #0e6b4f, multiply.\n  feathered / soft-edged (colour): Soft edges on the thing's colour: \"feathered 12\". e.g. Make the core #ffd166, feathered 6.\n  grayscale / greyscale / monochrome (state): Removes the colour from what the thing shows. e.g. Make the photo grayscale.\n  sepia (state): A warm brown tone. e.g. Make the photo sepia.\n  inverted / negative (state): Swaps light and dark. e.g. Make the photo inverted.\n  blurred / blurry / out-of-focus (state): Blurs what the thing shows: \"blurred 6\". e.g. Make the photo blurred 6.\n  brighter / lighter (state): Brightens it: \"20% brighter\". e.g. Make the photo 20% brighter.\n  darker / dimmer (state): Darkens it: \"20% darker\". e.g. Make the photo 20% darker.\n  vivid / saturated / punchy (state): Stronger colours. e.g. Make the photo vivid.\n  muted / desaturated / washed-out (state): Weaker colours. e.g. Make the photo muted.\n  contrasty / high-contrast (state): More contrast. e.g. Make the photo contrasty.\n  uppercase / capitals / caps (state): Sets text in capitals. e.g. Make the title uppercase.\n  lowercase (state): Sets text in small letters. e.g. Make the title lowercase.\n  bigger / larger (transform): Scales the thing up: \"1.6 times bigger\", \"20% bigger\". Without a number, a quarter bigger. e.g. Make the leaf 1.6 times bigger.\n  smaller (transform): Scales the thing down: \"20% smaller\", \"2 times smaller\". e.g. Make the badge 20% smaller.\n  wide (transform): Scales the thing to a width: \"780 wide\". e.g. Make the title 780 wide.\n  tall / high (transform): Scales the thing to a height: \"300 tall\". e.g. Make the badge 300 tall.\n  turned / tilted / rotated (transform): Turns the thing by degrees. e.g. Make the leaf turned -24.\n  hollow / hollowed / line-drawn (transform): Draws the thing as a line instead of solid: \"hollow, 3 wide\". e.g. Make the orbit hollow, 3 wide.\n  solid / filled (transform): Draws a hollow thing solid again. e.g. Make the orbit solid.\n  dashed / dotted (transform): Turns the thing's lines into dashes: \"dashed, 18 on 12 off\" (\"dotted\" makes short dashes). e.g. Make the rule dashed, 18 on 12 off.\n  flipped / mirrored (transform): Flips the thing left to right (\"flipped upside down\" for top to bottom). e.g. Make the leaf flipped.\n  line up / lined up / aligned / align (transform): Lines things up by an edge or centre: on the left, right, top, bottom, centre or middle. One thing lines up with the page. e.g. Make the title and the body line up on the left.\n  evenly spaced / spaced evenly / spread out / spread evenly (transform): Spaces three or more things evenly: horizontally or vertically. e.g. Make the one, the two and the three evenly spaced horizontally.\n  float / floating / bob / bobbing (motion): Bobs up and down for the whole video: \"14 high, every 3 s\". e.g. Make the badge float, 14 high, every 3 s.\n  pulse / pulsing / breathe / breathing (motion): Grows and shrinks a little, over and over: \"by 0.06, every 1.2 s\". e.g. Make the button pulse, by 0.06, every 1.2 s.\n  sway / swaying / rock / rocking (motion): Rocks from side to side: \"5 degrees, every 2 s\". e.g. Make the tag sway, 5 degrees, every 2 s.\n  spin / spinning (motion): Keeps turning: \"every 4 s\" is one turn. e.g. Make the wheel spin, every 3 s.\n  fade in / appear (motion): Fades the object in: \"at 1 s, over 0.5 s\". e.g. Make the title fade in at 1 s, over 0.5 s.\n  fade out / disappear / vanish (motion): Fades the object out: \"at 4 s, over 0.4 s\". e.g. Make the title fade out at 4 s.\n  readable / legible (colour): Light or dark, whichever reads best against what is under the thing. Give the two to choose from: \"readable, bone or ink\" (default white or near-black). e.g. Make the labels readable, bone or ink.","core":false},{"id":"video","title":"Video: move, change, motions, events","about":"Video: move, change, motions, events","text":"Video:\n- \"Move the ball to 880 300, at 0.5 s, over 1.4 s, bouncing.\" (bouncing, elastic, overshooting, linear) \"Move the ball 300 down over 0.6 s.\"\n- \"Change the banner to visible over 0.4 s.\" \"Change the ball to 130% size for 0.3 s, then back.\" States: visible, invisible,\n  N% size, turned N.\n- \"Make the badge float, 14 high, every 3 s.\" Also pulse, sway, spin, fade in, fade out.\n- Events instead of adding up seconds: \"When the video reaches 0.5 s, move the ball …\" \"When the ball arrives, change the\n  banner to visible over 0.4 s.\" \"When the banner appears, make the banner pulse.\" Moments: the video starts, the video\n  reaches N s, the video ends, <object> arrives, <object> appears, <object> leaves.\n- Only objects (cards, papers, plates let on the stage) move, change and take motion. Colours do not change over time yet.","core":false},{"id":"layout","title":"Layout in words: margin, styles, in/under/beside, labels, readable colour, tables","about":"Layout in words: margin, styles, in/under/beside, labels, readable colour, tables","text":"Layout in words (prefer this to coordinates; give positions only to the first big panels):\n- Page: \"Let the margin be 120.\" \"Let text be in Jost, size 26, aligned left.\" (every Write starts from it)\n- Styles: \"Let a heading be Martian Mono, size 26, tracking 6, brass.\" then 'Write \"01  COLOUR\" called h-colour as a heading, under the cover, 110 apart.'\n- Places: \"in the sticker\" (centred inside), \"in the cover, at the bottom left, 120 in\", \"at the top right\" (the page,\n  inside the margin), \"under the heading, 40 apart\", \"above …\", \"beside the play, 16 apart\", \"left of …\". Shapes:\n  \"Let there be a triangle called icon, 22 big, pointing right, in the play.\" (centred by eye). \"Move the x under the y.\"\n- Labels, one each: 'Write \"Oxblood\", \"Midnight\", \"Forest\" in each swatch, at the bottom left, 20 in.' then\n  \"Make the swatch-labels readable, bone or ink.\" (picks whichever reads best on what is under each).\n- Tables: \"Let there be a table called playlist, 1436 by 448, at 800 650, 8 rows, columns at 28, 78, 818 and 1398 right,\n  in Jost, size 24.\" then 'Write \"1\", \"Lanterns\", \"Vesper Lane\", \"4:07\" in the next row of the playlist.' Colour them with\n  \"Make every other playlist-row #edf3fb.\", \"Make the third playlist-words white.\", \"Make the playlist-column-4 #888888.\"\n- Names must not start with a digit: write \"called h-type\" rather than relying on \"02 TYPE\".\n\nNever name a thing a, an, the, it, ring, outline, edge or halo.","core":false},{"id":"names","title":"Names you may use: materials, colours, fonts, shapes, styles, pigments, stocks","about":"the exact names of materials, colours, fonts and shapes","text":"# Names you may use\nMaterials: gold-24k, gold, gold 24k, 24k gold, yellow gold, gold-yellow, bright gold, rose-gold, rose gold, silver, sterling, copper, gunmetal, gun metal, black-chrome, black chrome, pvd-blue-titanium, blue titanium, pvd blue, pvd-purple, purple pvd, purple metal, yellow-foil, yellow foil, lime-foil, lime foil, neon foil, orange-foil, orange foil, ruby, red metal, garnet, oxblood, mirror-chrome, chrome, mirror chrome, mirror, mirror-gold, mirror gold, gold mirror, mirror-black, black mirror, mirror black, mirror-rose, rose mirror, mirror rose, pink mirror, silk, rhinestone, rhinestones, glass-clear, clear glass, glass, glass-smoke, smoke glass, smoked glass, glass-rose, rose glass, niello, black enamel, ivory, ivory pearl, ivory enamel, glow, glow enamel, glow in the dark, brass, stainless, aluminium, titanium, anodized-navy, anodized navy, anodised navy, anodized-midnight, anodized midnight, anodised midnight, anodized-black, anodized black, anodised black\nColours: black, white, cream, red, crimson, pink, blush, orange, yellow, green, jade, mint, teal, blue, navy, sky, purple, lilac, brown, grey, gray, pale gold, deep gold, champagne\nFonts: Big Shoulders Display, Bodoni Moda, Herr Von Muellerhoff, Homemade Apple, Jost, Lilita One, Martian Mono, Michroma, Mr Dafoe, Mrs Saint Delafield, Permanent Marker, Rock Salt, Saira Condensed, Sedgwick Ave Display, Shrikhand\nShapes and patterns (draw a <shape> called …): bezel, rule, band, ironwork, studs, jewels, rims, beads, vine, dots, crosshatch, damask, rays, circle, ellipse, rectangle, star, triangle, diamond, pentagon, hexagon, octagon, heart, arrow, bubble, spiral, shape, line, curve\nStyles (use the <style> style.): studded-bezel\nPaints for spraying are mixed first: \"mix a paint called teal from 2 parts phthalo blue and 1 part titanium white, gloss.\"\nPigments: titanium white, zinc white, carbon black, ivory black, cadmium red, cadmium orange, cadmium yellow, hansa yellow, quinacridone magenta, ultramarine blue, phthalo blue, phthalo green, burnt sienna, yellow ochre, raw umber\nStocks for scene and video objects (make a paper/card/plate called … from <stock>): bond, newsprint, kraft, cardstock, black-card, stainless, brass, gold, copper, ink, acrylic","core":false},{"id":"verb:create","title":"Verb: create / start","about":"Start a card, or a canvas of any size. Everything after \"called\" names it; modifiers set the blank. Add \"flat\" to a canvas, stage or video f","text":"create / start\n  Start a card, or a canvas of any size. Everything after \"called\" names it; modifiers set the blank. Add \"flat\" to a canvas, stage or video for exact, unlit colours (graphic design); without it the piece is a lit physical surface.\n    create a canvas called poster, 1080 by 1350, flat.\n    create a card called marilyn from stainless, 0.8 mm thick, seed 19260601.\n    create a canvas called post, 1080 by 1350.","core":false},{"id":"verb:set","title":"Verb: set","about":"Set a card setting: seed, bench (background colour), edition, title, brush angle, lights.","text":"set\n  Set a card setting: seed, bench (background colour), edition, title, brush angle, lights.\n    set the bench to #0e0f12.\n    set the edition to 1 of 100.\n    set the title to \"Marilyn\".","core":false},{"id":"verb:make","title":"Verb: make / give","about":"Shape a zone (\"make the window 756 by 1345, at 242 242, corners 9.\") or set the current subject (\"make it oxblood.\").","text":"make / give\n  Shape a zone (\"make the window 756 by 1345, at 242 242, corners 9.\") or set the current subject (\"make it oxblood.\").\n    make the window 756 by 1345, centred, corners 9.\n    make a zone called badge 200 by 80, at 520 1500.","core":false},{"id":"verb:define","title":"Verb: define","about":"Name a value or a recipe. Values are pasted wherever $name appears; recipes run with \"use\".","text":"define\n  Name a value or a recipe. Values are pasted wherever $name appears; recipes run with \"use\".\n    define $chrome as mirror chrome.\n    define $pitch as 38.\n    define $finish as:\n  plate it with $chrome.\n  outline it in niello, 6 wide.\nend.","core":false},{"id":"verb:use","title":"Verb: use / apply","about":"Run a recipe ($name) or a built-in style (\"the studded bezel style\").","text":"use / apply\n  Run a recipe ($name) or a built-in style (\"the studded bezel style\").\n    use $finish.\n    use the studded bezel style.","core":false},{"id":"verb:on","title":"Verb: on","about":"Choose the side the following steps are made on.","text":"on\n  Choose the side the following steps are made on.\n    on the front.\n    on the back.","core":false},{"id":"verb:let","title":"Verb: let","about":"Let a layer break out of the card outline (digital cards).","text":"let\n  Let a layer break out of the card outline (digital cards).\n    let the frame break the card edge.","core":false},{"id":"verb:brush","title":"Verb: brush","about":"Brush the blank: the grain angle in degrees.","text":"brush\n  Brush the blank: the grain angle in degrees.\n    brush the card at 35 degrees.","core":false},{"id":"verb:plate","title":"Verb: plate / coat","about":"Electroplate or PVD a metal onto an area.","text":"plate / coat\n  Electroplate or PVD a metal onto an area.\n    plate the frame with chrome.\n    plate the card with black mirror.\n    plate it with $gold, satin.","core":false},{"id":"verb:foil","title":"Verb: foil / hot-foil","about":"Hot-foil a metal or holo foil, slightly raised.","text":"foil / hot-foil\n  Hot-foil a metal or holo foil, slightly raised.\n    foil the rays with silk holo.","core":false},{"id":"verb:engrave","title":"Verb: engrave / cut","about":"Cut into the surface. Depth in mm (default 0.04).","text":"engrave / cut\n  Cut into the surface. Depth in mm (default 0.04).\n    engrave the vine, 0.04 mm deep.","core":false},{"id":"verb:enamel","title":"Verb: enamel / fill / colour / color / paint","about":"Fill an area with enamel colour (sits in the last engraving). A gradient: \"in a gradient from #a to #b, angled 45\" or \"in a radial gradient ","text":"enamel / fill / colour / color / paint\n  Fill an area with enamel colour (sits in the last engraving). A gradient: \"in a gradient from #a to #b, angled 45\" or \"in a radial gradient from …\". Add \"60% opacity\" or a blend mode (multiply, screen, overlay…). \"fill … with crosshatch\" draws a pattern instead.\n    enamel the vine in ivory.\n    enamel it in #efe6d8.\n    enamel the card in a gradient from #0b1d51 to #e94f37, angled 45.\n    enamel the badge in #ffffff, 40% opacity, multiply.","core":false},{"id":"verb:adjust","title":"Verb: adjust / filter","about":"An adjustment layer: changes everything already painted under an area. blurred 12 (frosted glass), brightness 1.1, contrast 1.2, saturation ","text":"adjust / filter\n  An adjustment layer: changes everything already painted under an area. blurred 12 (frosted glass), brightness 1.1, contrast 1.2, saturation 0.6, hue 40, grayscale, sepia, inverted. Write it after the things it should change.\n    adjust the panel, blurred 14, brightness 1.1.\n    adjust the card, grayscale, contrast 1.2.","core":false},{"id":"verb:vignette","title":"Verb: vignette","about":"Darken (or tint) the edges of an area, leaving its middle clear: an amount from 0 to 1 (default 0.5), optionally \"in #colour\".","text":"vignette\n  Darken (or tint) the edges of an area, leaving its middle clear: an amount from 0 to 1 (default 0.5), optionally \"in #colour\".\n    vignette the card, 0.6.\n    vignette the photo, 0.5, in #1b1145.","core":false},{"id":"verb:grain","title":"Verb: grain / noise","about":"Film grain over an area, for texture: an amount from 0 to 1 (default 0.25). \"coarse\" makes bigger grains.","text":"grain / noise\n  Film grain over an area, for texture: an amount from 0 to 1 (default 0.25). \"coarse\" makes bigger grains.\n    grain the card, 0.3.\n    grain the card, 0.2, coarse.","core":false},{"id":"verb:stroke","title":"Verb: stroke","about":"A flat outline round an area, outside its edge: \"stroke the title in #ffffff, 6 wide.\" (Without a colour, \"stroke the petal, 3 wide\" draws a","text":"stroke\n  A flat outline round an area, outside its edge: \"stroke the title in #ffffff, 6 wide.\" (Without a colour, \"stroke the petal, 3 wide\" draws a shape as a line, like \"hollow\".)\n    stroke the title in #ffffff, 6 wide.\n    stroke the badge in gold, 10 wide, 80% opacity.","core":false},{"id":"verb:shadow","title":"Verb: shadow","about":"A soft drop shadow under an area. Write it before the steps that colour the area, so the area sits on its shadow. Defaults: 10 down, blur 18","text":"shadow\n  A soft drop shadow under an area. Write it before the steps that colour the area, so the area sits on its shadow. Defaults: 10 down, blur 18, black, 45% opacity. Add \"inside\" for an inner shadow (written after the colour), which makes the area look cut in.\n    shadow the headline, 14 down, 6 right, blur 24, in #000000, 50% opacity.\n    shadow the panel, inside, 6 down, blur 16, 50% opacity.","core":false},{"id":"verb:glow","title":"Verb: glow","about":"A glow of light round an area (outer glow). Write it before the steps that colour the area. Defaults: white, 30 wide, strength 1.","text":"glow\n  A glow of light round an area (outer glow). Write it before the steps that colour the area. Defaults: white, 30 wide, strength 1.\n    glow the headline in #ffd54a, 40 wide, strength 2.","core":false},{"id":"verb:inlay","title":"Verb: inlay","about":"Engrave and fill with enamel in one go.","text":"inlay\n  Engrave and fill with enamel in one go.\n    inlay the vine with ivory, 0.04 mm deep.","core":false},{"id":"verb:outline","title":"Verb: outline","about":"Engrave a ring around an area and fill it (default niello, 6 wide).","text":"outline\n  Engrave a ring around an area and fill it (default niello, 6 wide).\n    outline the frame in niello, 6 wide.\n    outline the signature, 9 wide.","core":false},{"id":"verb:emboss","title":"Verb: emboss / raise","about":"Raise an area. Height in mm (default 0.12); \"soft 0.7\" rounds it.","text":"emboss / raise\n  Raise an area. Height in mm (default 0.12); \"soft 0.7\" rounds it.\n    emboss the frame, 0.16 mm high, soft 0.7.","core":false},{"id":"verb:deboss","title":"Verb: deboss / press / sink","about":"Press an area down. Depth in mm (default 0.04).","text":"deboss / press / sink\n  Press an area down. Depth in mm (default 0.04).\n    deboss the badge, 0.04 mm deep.","core":false},{"id":"verb:etch","title":"Verb: etch / frost","about":"Frost or matte-etch an area.","text":"etch / frost\n  Frost or matte-etch an area.\n    etch the background.","core":false},{"id":"verb:spray","title":"Verb: spray","about":"Spray a coat: gloss, candy, glitter, metalflake, pearl, chameleon or matte. \"in\" takes colours.","text":"spray\n  Spray a coat: gloss, candy, glitter, metalflake, pearl, chameleon or matte. \"in\" takes colours.\n    spray the window with gloss, 30 µm thick.\n    spray the signature with glitter in pale gold and deep gold, flakes 110 µm, density 0.7.","core":false},{"id":"verb:print","title":"Verb: print","about":"Print a photo or illustration into an area (default: the window); printed in a shape, the photo fills that shape. Adjust it: duotone #1b1145","text":"print\n  Print a photo or illustration into an area (default: the window); printed in a shape, the photo fills that shape. Adjust it: duotone #1b1145 and #ffb347, blurred 6, brightness 1.2, contrast 1.1, saturation 0.5, hue 40, grayscale, sepia, inverted, 70% opacity, multiply. \"on foil\" prints see-through onto metal.\n    print @photo.jpg in the badge, grayscale, contrast 1.2.\n    print @marilyn.jpg in the window, focused at 0.5 0.2.\n    print @star.png on foil, white under the figure.","core":false},{"id":"verb:illustrate","title":"Verb: illustrate","about":"Cloisonné: turn an illustration into flat enamel cells with metal wires.","text":"illustrate\n  Cloisonné: turn an illustration into flat enamel cells with metal wires.\n    illustrate @mansion.jpg in the window, 16 colours.","core":false},{"id":"verb:write","title":"Verb: write / type / letter","about":"Set words in a font. Defaults: Bodoni Moda, size 48, centred. Several lines: put \\n in the words, or wrap with \"600 wide\"; \"leading 1.2\" set","text":"write / type / letter\n  Set words in a font. Defaults: Bodoni Moda, size 48, centred. Several lines: put \\n in the words, or wrap with \"600 wide\"; \"leading 1.2\" sets the line spacing; \"aligned left\" or \"aligned right\"; \"uppercase\"; \"tracking 4\". \"curved 400\" sets the words on an arc of that radius (negative curves the other way). Placed by words: \"in the sticker\", \"in the cover, at the bottom left, 120 in\", \"at the top right\" (the page, inside the margin), \"under the heading, 40 apart\", \"beside the play, 16 apart\". \"as a heading\" uses a style made with \"Let a heading be …\". Several words at once give one label each: Write \"a\", \"b\" in each swatch. In a table: Write \"1\", \"Lanterns\" in the next row of the playlist.\n    write \"Summer\\nSale\" called title in Lilita One, at 540 500, size 160, leading 0.95.\n    write \"A long line that wraps\" called body in Jost, at 120 900, size 40, 600 wide, aligned left.\n    write \"LIMITED EDITION\" called arc in Jost, at 540 300, size 44, curved 320, tracking 6.\n    write \"BIG NEWS\" called shout in Lilita One, at 540 400, fit 900, turned -4.\n    write \"fancard\" called wordmark in Bodoni Moda italic, at 620 230, size 58.\n    Write \"NEW!\" called new in Lilita One, size 48, in the sticker.\n    Write \"Oxblood\", \"Midnight\", \"Forest\" in each swatch, at the bottom left, 20 in.","core":false},{"id":"verb:sign","title":"Verb: sign","about":"A script signature fitted to a spot. Defaults: Herr Von Muellerhoff, 620 wide, size 250, near the bottom.","text":"sign\n  A script signature fitted to a spot. Defaults: Herr Von Muellerhoff, 620 wide, size 250, near the bottom.\n    sign \"Marilyn\" in Herr Von Muellerhoff, at 620 1478, 620 wide, size 250, tilted -6.\n    sign $name called back-signature, at 620 900.","core":false},{"id":"verb:draw","title":"Verb: draw / grow / add / scatter / carve","about":"Draw a generator as a named layer: bezel, rule, band, ironwork, studs, jewels, rims, beads, vine, dots, crosshatch, damask, rays — or a path","text":"draw / grow / add / scatter / carve\n  Draw a generator as a named layer: bezel, rule, band, ironwork, studs, jewels, rims, beads, vine, dots, crosshatch, damask, rays — or a path, or a drawing (@sketch.svg).\n    draw a bezel called frame.\n    grow a vine along the card, 88 in, leaving a gap at the top.\n    draw @sketch-1.svg called heart.\n    draw a path called tag, \"M100 100 L300 100 L200 260 Z\".\n    draw a path called leaf, \"M0 0 C40 -60 120 -60 160 0 C120 60 40 60 0 0 Z\", at 400 700, scale 1.5, turned -20.","core":false},{"id":"verb:move","title":"Verb: move / shift / slide","about":"Move elements: \"to 620 900\" (its centre), \"by 10 -20\", or \"up by 40\".","text":"move / shift / slide\n  Move elements: \"to 620 900\" (its centre), \"by 10 -20\", or \"up by 40\".\n    move the petal up by 24.\n    move it to 620 900.\n    move the tail by -300 30.","core":false},{"id":"verb:turn","title":"Verb: turn / rotate / spin / tilt","about":"Turn elements by degrees, round their centre (inside a definition: round 0 0) or \"around x y\".","text":"turn / rotate / spin / tilt\n  Turn elements by degrees, round their centre (inside a definition: round 0 0) or \"around x y\".\n    turn the plane 35 degrees.\n    turn the petal 72 degrees around 0 0.","core":false},{"id":"verb:scale","title":"Verb: scale / resize / grow-by / shrink","about":"Scale elements: \"by 0.6\", or \"by 1.2 0.8\" for width and height separately.","text":"scale / resize / grow-by / shrink\n  Scale elements: \"by 0.6\", or \"by 1.2 0.8\" for width and height separately.\n    scale the petals by 0.6.\n    scale it by 1.5 around 620 900.","core":false},{"id":"verb:flip","title":"Verb: flip","about":"Flip elements in place: left to right, or \"upside down\".","text":"flip\n  Flip elements in place: left to right, or \"upside down\".\n    flip the wing.\n    flip it upside down.","core":false},{"id":"verb:mirror","title":"Verb: mirror","about":"Add a mirror image, making the element symmetric: across a vertical line (default) or \"horizontally\". \"at 620\" sets the line.","text":"mirror\n  Add a mirror image, making the element symmetric: across a vertical line (default) or \"horizontally\". \"at 620\" sets the line.\n    mirror the wing.\n    mirror the tail at 0.\n    mirror the leaf horizontally.","core":false},{"id":"verb:copy","title":"Verb: copy / repeat / duplicate","about":"Copy elements: \"5 times around 0 0\" (a ring), \"4 times, 120 apart\" (a row), \"6 times, 60 apart, 4 rows\" (a grid), or once with changes. A lo","text":"copy / repeat / duplicate\n  Copy elements: \"5 times around 0 0\" (a ring), \"4 times, 120 apart\" (a row), \"6 times, 60 apart, 4 rows\" (a grid), or once with changes. A loop: \"repeat 6 times as: … end.\" runs the statements inside six times with $n counting 1 to 6 and $i counting from 0 (use them in sums: \"(40 * $n) big\"); what each pass draws is named orbit-1, orbit-2, … and \"the orbit\" means all of them (\"scale 0.6, turn 36, called inner\").\n    copy the petal 5 times around 0 0.\n    copy the petals, scale 0.6, turn 36, called inner-petals.\n    copy the star 4 times, 90 apart.\n    copy the dot 8 times, 50 apart, 5 rows.\n    repeat 6 times as:\n  draw a circle called orbit, (40 * $n) big, at 540 675, hollow 3.\nend.","core":false},{"id":"verb:hollow","title":"Verb: hollow","about":"Draw elements as lines instead of solid: \"4 wide\".","text":"hollow\n  Draw elements as lines instead of solid: \"4 wide\".\n    hollow the petals, 3 wide.","core":false},{"id":"verb:solidify","title":"Verb: solidify / make-solid","about":"(the opposite of hollow; also \"fill it.\")","text":"solidify / make-solid\n  (the opposite of hollow; also \"fill it.\")\n    solidify the rose.\n    fill it.","core":false},{"id":"verb:dash","title":"Verb: dash","about":"Turn lines into dashes: \"18 on 12 off\".","text":"dash\n  Turn lines into dashes: \"18 on 12 off\".\n    dash the trail, 18 on 12 off.","core":false},{"id":"verb:group","title":"Verb: group / join / combine","about":"Gather elements into one: \"group the wings and the keel as plane.\"","text":"group / join / combine\n  Gather elements into one: \"group the wings and the keel as plane.\"\n    group the wings and the keel as plane.","core":false},{"id":"verb:align","title":"Verb: align / line-up","about":"Line shapes and text up by their edges or centres: left, right, top, bottom, centre (left to right) or middle (top to bottom). Several thing","text":"align / line-up\n  Line shapes and text up by their edges or centres: left, right, top, bottom, centre (left to right) or middle (top to bottom). Several things align to the group they make; one thing aligns to the canvas. \"20 in\" keeps a margin from the canvas edge.\n    align the title and the body to the left.\n    align the badge to the centre.\n    align the logo to the right, 60 in.","core":false},{"id":"verb:distribute","title":"Verb: distribute / space","about":"Space three or more shapes or texts evenly between the first and the last: \"horizontally\" (default) or \"vertically\". \"40 apart\" sets the gap","text":"distribute / space\n  Space three or more shapes or texts evenly between the first and the last: \"horizontally\" (default) or \"vertically\". \"40 apart\" sets the gap instead.\n    distribute the one, the two and the three horizontally.\n    distribute the rows vertically, 24 apart.","core":false},{"id":"verb:place","title":"Verb: place / put / stamp","about":"Place a defined object (see \"define a … as:\"), with its settings: \"place a rose at 620 900, size 90, petals 7, turned 15.\" Several: \"place 3","text":"place / put / stamp\n  Place a defined object (see \"define a … as:\"), with its settings: \"place a rose at 620 900, size 90, petals 7, turned 15.\" Several: \"place 3 roses from 300 1300, 160 apart.\"\n    place a rose called big-rose at 620 1250, size 120, turned 10.\n    place 3 roses from 380 1500, 240 apart, size 50.","core":false},{"id":"verb:slam","title":"Verb: slam","about":"Slam an element down onto the stage at a time, like a rubber stamp: \"slam the sell-stamp in at 7 s.\"","text":"slam\n  Slam an element down onto the stage at a time, like a rubber stamp: \"slam the sell-stamp in at 7 s.\"\n    slam the sell-stamp in at 7 s.","core":false},{"id":"verb:remove","title":"Verb: remove","about":"Take an element off the stage at a time: \"remove the title at 4 s, to the left.\" Or in place: shrinking, fading or sinking.","text":"remove\n  Take an element off the stage at a time: \"remove the title at 4 s, to the left.\" Or in place: shrinking, fading or sinking.\n    remove the title at 4 s, to the left.","core":false},{"id":"verb:fade","title":"Verb: fade","about":"Fade an element in or out over time: \"fade in the title at 1 s, over 0.5 s.\" \"fade out the title at 4 s, over 0.4 s.\"","text":"fade\n  Fade an element in or out over time: \"fade in the title at 1 s, over 0.5 s.\" \"fade out the title at 4 s, over 0.4 s.\"\n    fade in the title at 1 s, over 0.5 s.\n    fade out the title at 4 s, over 0.4 s.","core":false},{"id":"verb:float","title":"Verb: float / pulse / sway / bob / breathe / rock","about":"Motion that keeps going for the whole video: \"float the badge, 14 high, every 3 s.\" \"pulse the button, by 0.06, every 1.2 s.\" \"sway the tag,","text":"float / pulse / sway / bob / breathe / rock\n  Motion that keeps going for the whole video: \"float the badge, 14 high, every 3 s.\" \"pulse the button, by 0.06, every 1.2 s.\" \"sway the tag, 5 degrees, every 2 s.\" A wheel that keeps turning: \"turn the wheel, every 4 s.\"\n    float the badge, 14 high, every 3 s.\n    pulse the button, by 0.06, every 1.2 s.\n    sway the tag, 5 degrees, every 2 s.","core":false},{"id":"verb:glide","title":"Verb: glide","about":"Move an element (or the camera) to a new place over time: \"glide the chart to 540 700, turned 3, at 9 s, over 0.6 s.\" \"glide the camera to 7","text":"glide\n  Move an element (or the camera) to a new place over time: \"glide the chart to 540 700, turned 3, at 9 s, over 0.6 s.\" \"glide the camera to 700 600, zoom 1.2, at 9 s, over 0.5 s.\" The motion eases in and out unless you add: linear, ease-in, ease-out, overshoot, bounce or elastic.\n    glide the camera to 700 600, zoom 1.2, at 9 s, over 0.5 s.","core":false},{"id":"verb:caption","title":"Verb: caption / say","about":"A caption that appears word by word: caption \"TEXT\" at T s, for D s, \"keyword\" in #colour.","text":"caption / say\n  A caption that appears word by word: caption \"TEXT\" at T s, for D s, \"keyword\" in #colour.\n    caption \"Prices snap back.\" at 1 s, for 3 s, \"snap back\" in #c8361f.","core":false},{"id":"verb:style","title":"Verb: style","about":"Caption style: \"style the captions in Jost, size 62, #1d1b18, at 1560.\"","text":"style\n  Caption style: \"style the captions in Jost, size 62, #1d1b18, at 1560.\"\n    style the captions in Jost, size 62, #1d1b18, at 1560.","core":false},{"id":"verb:reveal","title":"Verb: reveal / show","about":"Reveal a layer over time, as if drawn or written: \"reveal the price at 5 s, over 3 s, from the left.\"","text":"reveal / show\n  Reveal a layer over time, as if drawn or written: \"reveal the price at 5 s, over 3 s, from the left.\"\n    reveal the price at 5 s, over 3 s, from the left.","core":false},{"id":"verb:bring","title":"Verb: bring / send","about":"Change stacking: \"bring the memo to the front\", \"send the seal to the back\", \"send the seal behind the memo\". In a video, \"bring in the memo","text":"bring / send\n  Change stacking: \"bring the memo to the front\", \"send the seal to the back\", \"send the seal behind the memo\". In a video, \"bring in the memo at 1 s, from the left\" makes an entrance; instead of a side it can arrive popping, rising, zooming or fading.\n    bring the memo to the front.\n    send the seal behind the memo.\n    bring in the badge at 1.2 s, popping.","core":false},{"id":"verb:mix","title":"Verb: mix","about":"Mix a paint from pigments (Kubelka-Munk, like real paint): parts, \"a touch of\", \"a little\"; then a finish.","text":"mix\n  Mix a paint from pigments (Kubelka-Munk, like real paint): parts, \"a touch of\", \"a little\"; then a finish.\n    mix a paint called leaf from 1 part phthalo blue and 2 parts hansa yellow, satin.","core":false},{"id":"verb:let-2","title":"Verb: let (plain English)","about":"Brings a thing into being: \"Let there be a flat canvas called poster, 1080 by 1350.\" \"Let there be a circle called sun, 330 big, at 800 330.","text":"let\n  Brings a thing into being: \"Let there be a flat canvas called poster, 1080 by 1350.\" \"Let there be a circle called sun, 330 big, at 800 330.\" Several at once, instead of a loop: \"Let there be 9 circles called orbit, at 540 560, the first 70 big, each 70 bigger than the last.\", \"… in a row, 46 apart\", \"… in a grid 8 by 5, 46 apart, from 70 70\", \"… in a ring around 540 560, 450 out\", \"each turned 30 more\". Afterwards \"the orbits\" means all of them, and \"the third orbit\", \"the last orbit\" or \"every other orbit\" picks some. Also names a value: \"Let gold be #ffb347.\" Layout: \"Let the margin be 120.\", \"Let text be in Jost, size 26, aligned left.\", \"Let a heading be Martian Mono, size 26, tracking 6, brass.\" Things can be placed when they are made (\"…, under the heading, 40 apart\", \"…, pointing right, in the play\"). A table: \"Let there be a table called playlist, 1436 by 448, at 800 650, 8 rows, columns at 28, 78, 818 and 1398 right, in Jost, size 24.\"\n    Let there be a flat canvas called poster, 1080 by 1350.\n    Let there be a circle called sun, 330 big, at 800 330.\n    Let there be 12 triangles called ray, 46 by 150, in a ring around 540 560, 450 out.\n    Let gold be #ffb347.\n    Let the margin be 120.\n    Let a heading be Martian Mono, size 26, tracking 6, #c19a4b.\n    Let there be a triangle called icon, 22 big, pointing right, in the play.","core":false},{"id":"verb:make-2","title":"Verb: make (plain English)","about":"Applies a known word to a thing. A colour or material: \"make the card #10131f\", \"make the title gold\". An effect: glow, shadowed, outlined, ","text":"make\n  Applies a known word to a thing. A colour or material: \"make the card #10131f\", \"make the title gold\". An effect: glow, shadowed, outlined, frosted, grainy, vignetted. A state: grayscale, blurred 6, 40% see-through, uppercase. A transform: bigger, 780 wide, turned -24, flipped, line up on the left. A motion (video): float, pulse, sway, spin, fade in. Details follow as commas, and several words can share a sentence: \"make the title gold, shadowed and uppercase.\" (Also shapes a zone: \"make the window 756 by 1345.\")\n    make the card #10131f.\n    make the sun glow in #ffd98a, 90 wide.\n    make the title gold, shadowed and uppercase.\n    make the leaf 1.6 times bigger, turned -24.\n    make the badge float, 14 high, every 3 s.","core":false},{"id":"verb:give","title":"Verb: give","about":"Gives a thing something it has: \"give the title a shadow, 10 down, blur 14\", \"give the card the colour #10131f\", \"give the card a vignette o","text":"give\n  Gives a thing something it has: \"give the title a shadow, 10 down, blur 14\", \"give the card the colour #10131f\", \"give the card a vignette of 0.35\". Also sets one value: \"give the title a size of 170\", \"give the glow a width of 90\" (width, blur, strength, colour, opacity).\n    give the title a shadow, 10 down, blur 14.\n    give the card a grain of 0.2.\n    give the glow a width of 90.","core":false},{"id":"verb:move-2","title":"Verb: move (plain English)","about":"Puts a thing somewhere else: \"move the badge to 540 300\", \"move the badge 40 right, 20 down\". With a time it travels there (an object in a v","text":"move\n  Puts a thing somewhere else: \"move the badge to 540 300\", \"move the badge 40 right, 20 down\". With a time it travels there (an object in a video): \"move the ball to 880 300 over 1.4 s, bouncing\" (bouncing, elastic, overshooting, linear, ease-in, ease-out). Or by words: \"move the badge under the title, 20 apart\", \"move the badge in the panel, at the top right, 16 in\".\n    move the badge to 540 300.\n    move the title 40 right, 20 down.\n    move the ball to 880 300, at 0.5 s, over 1.4 s, bouncing.\n    move the badge beside the title, 24 apart.","core":false},{"id":"verb:change","title":"Verb: change","about":"A change over time, for an object in a video: \"change the title to invisible over 0.5 s\", \"change the badge to 120% size for 0.5 s, then bac","text":"change\n  A change over time, for an object in a video: \"change the title to invisible over 0.5 s\", \"change the badge to 120% size for 0.5 s, then back\", \"change the tag to turned 20 over 1 s\". States: visible, invisible, N% size, N times bigger, turned N. \"for N s\" holds it and returns; \"then back\" returns after a moment. Use \"move\" for place.\n    change the title from invisible to visible over 0.5 s.\n    change the badge to 120% size for 0.5 s, then back.","core":false},{"id":"verb:when","title":"Verb: when / once / after","about":"An event in a video: the rest of the sentence happens at that moment. Moments: \"the video starts\", \"the video reaches 2 s\" (or \"after 2 s\"),","text":"when / once / after\n  An event in a video: the rest of the sentence happens at that moment. Moments: \"the video starts\", \"the video reaches 2 s\" (or \"after 2 s\"), \"the video ends\", and what an object does: \"the ball arrives\" (its move ends), \"the title appears\", \"the title leaves\". Chain them, so nobody adds up seconds.\n    When the video reaches 2 s, move the ball to 880 300 over 1.4 s, bouncing.\n    When the ball arrives, make the banner pulse.\n    When the title appears, change the badge to 120% size for 0.4 s, then back.","core":false},{"id":"example:the-smallest-card","title":"Example: The smallest card","about":"The smallest card","text":"## The smallest card\n```gt\n-- The smallest card: a chrome bezel on black mirror, with a name.\ncreate a card called hello.\ndraw a bezel called frame.\non the front.\nplate the card with black mirror.\nplate the frame with chrome.\nsign \"Hello\" at 620 900.\nplate the signature with gold.\n```","core":false},{"id":"example:a-card-with-a-front","title":"Example: A card with a front and a back","about":"A card with a front and a back","text":"## A card with a front and a back\n```gt\n-- A ticket card for the desk: red enamel and a gold signature on the front, chrome and black mirror on the back.\ncreate a card called desk-ticket from brass, 0.8 mm thick.\non the front.\nenamel the card in #a8141d.\ndraw a bezel called frame.\nplate the frame with chrome.\nsign \"ADMIT ONE\" at 620 900.\nplate the signature with gold.\non the back.\nplate the card with black mirror.\ndraw a bezel called back-frame.\nplate the back-frame with chrome.\n```","core":false},{"id":"example:a-card-that-prints-an","title":"Example: A card that prints an image it was given","about":"A card that prints an image it was given","text":"## A card that prints an image it was given\n```gt\n-- Marilyn concept card, written in godtongue.\n-- The studded bezel style draws the frame; this file adds the photo, the lettering and the back.\n\ncreate a card called marilyn, seed 19260601.\nuse the studded bezel style.\n\non the front.\nuse $studded-finish.\nprint @marilyn.jpg in the window, focused at 0.5 0.2.\nspray the window with gloss, 30 µm thick.\nwrite \"fancard\" called wordmark in Bodoni Moda italic, at 620 230, size 58.\nsign \"Marilyn\" at 620 1478.\nuse $gild on the wordmark and the signature.\n\non the back.\nuse $studded-finish.\nfill the window with damask.\nsign \"Marilyn\" called back-signature, at 620 900, 680 wide, size 320.\ninlay the damask except the back-signature grown by 18 with ivory, 0.015 mm deep.\nuse $gild on the wordmark and the back-signature.\n```","core":false},{"id":"example:a-canvas-post","title":"Example: A canvas post","about":"A canvas post","text":"## A canvas post\n```gt\n-- First canvas piece: a 1080 by 1350 post, chrome headline on red enamel.\ncreate a canvas called post, 1080 by 1350.\n\nwrite \"SALE\" called headline in Lilita One, at 540 620, size 380.\nwrite \"THIS WEEKEND ONLY\" called sub in Martian Mono, at 540 820, size 44.\ndraw a circle called badge, 220 big, at 900 170.\nwrite \"50\" called pct in Lilita One, at 900 192, size 130.\n\non the front.\nenamel the card in #a8141d.\nemboss the headline, 0.2 mm high, soft 0.6.\nplate the headline with chrome.\nemboss the badge, 0.12 mm high.\nplate the badge with gold.\nengrave the pct, 0.05 mm deep.\ninlay the pct with #a8141d, 0.02 mm deep.\nengrave the sub, 0.03 mm deep.\ninlay the sub with #f4e3b0, 0.02 mm deep.\nspray the card with gloss, 30 µm thick.\n```","core":false},{"id":"example:a-flat-poster-drawn-with","title":"Example: A flat poster drawn with plurals (no loops)","about":"A flat poster drawn with plurals (no loops)","text":"## A flat poster drawn with plurals (no loops)\n```gt\n-- The flat pattern poster in plain English: no loops, and the order of the sentences does not matter.\nLet there be a flat canvas called pattern, 1080 by 1350.\nLet navy be #1f3a5f.\nLet ember be #e4572e.\n\nLet there be 9 circles called orbit, at 540 560, the first 70 big, each 70 bigger than the last, hollow 6.\nLet there be 12 triangles called ray, 46 by 150, in a ring around 540 560, 450 out.\nLet there be a circle called core, 150 big, at 540 560.\nWrite \"RADIAL\" called title in Big Shoulders Display bold, at 540 1150, fit 860.\nWrite \"drawn in plain English\" called sub in Jost, at 540 1240, size 40, tracking 6.\n\nMake the card #f4efe6, vignetted 0.35, in navy.\nMake the orbits navy, 30% see-through.\nMake the rays ember.\nMake the third ray navy.\nMake the core a radial gradient from #ffd166 to #e4572e, feathered 6.\nMake the title navy.\nMake the sub ember.\n```","core":false},{"id":"example:a-launch-poster-duotone-photo","title":"Example: A launch poster: duotone photo, frosted glass, fitted headline, shapes lined up (it was given @marilyn.jpg)","about":"A launch poster: duotone photo, frosted glass, fitted headline, shapes lined up (it was given @marilyn.jpg)","text":"## A launch poster: duotone photo, frosted glass, fitted headline, shapes lined up (it was given @marilyn.jpg)\n```gt\n-- The launch poster in plain English. The sentences are grouped by thing; their order does not matter.\nLet there be a canvas called launch, 1080 by 1350.\nMake the card #10131f, grainy 0.22.\n\nLet there be a rectangle called photo, 1080 by 760, at 540 380.\nPrint @marilyn.jpg in the photo, duotone #1b1145 and #ff9a5a, focused at 0.5 0.2.\n\nLet there be 40 circles called dot, 7 big, in a grid 8 by 5, 46 apart, from 70 70.\nMake the dots white, 65% see-through.\n\nLet there be a rectangle called glass, 900 by 330, corners 40, at 540 760.\nMake the glass frosted, white, 86% see-through.\nGive the glass a shadow, 20 down, blur 40, 55% opacity.\nGive the glass an outline in #ffffff, 2 wide, 45% opacity.\n\nWrite \"LAUNCH DAY\" called title in Lilita One, at 540 720, fit 780.\nWrite \"Friday 20 November · doors at seven\" called when in Jost, at 540 850, size 40.\nMake the title and the when line up on the left.\nMake the title a gradient from #fff3d6 to #ff9a5a, angled 90.\nGive the title an outline in #1b1145, 8 wide.\nMake the when white.\n\nLet there be a bubble called tag, 300 by 130, corners 36, at 850 150.\nWrite \"NEW!\" called new in Lilita One, at 850 172, size 70, turned -6.\nMake the tag #ff5d5d, shadowed.\nMake the new white.\n\nLet there be a hexagon called one, 70 big, corners 10, at 200 1090.\nLet there be a heart called two, 130 big, at 420 1100.\nLet there be a diamond called three, 70 big, at 700 1080.\nLet there be an arrow called four, 170 by 110, at 900 1120.\nMake the one, the two, the three and the four line up on the middle.\nMake the one, the two, the three and the four evenly spaced horizontally.\nMake the one #5ad1c9.\nMake the two #ff5d8f.\nMake the three #ffd166.\nMake the four #8f7bff.\nGive the one, the two, the three and the four an inner shadow, 6 down, blur 10, 45% opacity.\n\nWrite \"Things are made, given and moved in plain sentences, and they arrange themselves.\" called body in Jost, at 540 1255, size 30, 880 wide, leading 1.3.\nMake the body #c9cede.\n```","core":false},{"id":"example:a-brand-guide-laid-out","title":"Example: A brand guide laid out with words: margin, styles, placement, labels, readable colour (it was given @tiara-night.jpg, @hallows.jpg, @sienna-shoreline.jpg)","about":"A brand guide laid out with words: margin, styles, placement, labels, readable colour (it was given @tiara-night.jpg, @hallows.jpg, @sienna-shoreline.jpg)","text":"## A brand guide laid out with words: margin, styles, placement, labels, readable colour (it was given @tiara-night.jpg, @hallows.jpg, @sienna-shoreline.jpg)\n```gt\n-- Studio Morgana brand guide: one page. Deep colours, three typefaces, imagery, the wordmark on dark and light.\n-- Laid out with words: a margin, text styles, things placed under other things. Only the cover and the swatches\n-- are given positions; everything else follows them.\nLet there be a flat canvas called brand-guide, 1600 by 2400.\nLet the margin be 120.\nLet text be in Jost, size 26, aligned left.\nLet a heading be Martian Mono, size 26, tracking 6, brass.\nLet a note be leading 1.4, bone, 40% see-through.\nLet ink be #0b0b10.\nLet bone be #efe6d8.\nLet brass be #c19a4b.\nMake the card ink, grainy 0.12.\n\n-- the cover band\nLet there be a rectangle called cover, 1600 by 760, at 800 380.\nPrint @tiara-night.jpg in the cover, duotone #0b0b10 and #6e1a2e, focused at 0.5 0.3.\nGive the cover a vignette of 0.6, in #0b0b10.\nWrite \"Deep colour, sharp type, real light.\" called promise in Jost light, size 40, in the cover, at the bottom left, 120 in.\nWrite \"BRAND GUIDE · EDITION ONE · 2026\" called kicker in Martian Mono, tracking 6, above the promise, 24 apart.\nWrite \"Morgana\" called wordmark in Bodoni Moda italic, fit 900, above the kicker, 30 apart.\nMake the wordmark bone, shadowed, 12 down, blur 30, 50% opacity.\nMake the kicker brass.\nMake the promise bone, 25% see-through.\n\n-- 01 colour\nWrite \"01  COLOUR\" called h-colour as a heading, under the cover, 110 apart.\nLet there be 6 rectangles called swatch, 210 by 300, corners 24, in a row, 236 apart, under the h-colour, 40 apart.\nMake the first swatch #4a0e1c.\nMake the second swatch #0d1033.\nMake the third swatch #0f3b2e.\nMake the fourth swatch #2b0f2e.\nMake the fifth swatch brass.\nMake the sixth swatch bone.\nGive the swatches an outline in #ffffff, 1 wide, 88% see-through.\nWrite \"Oxblood\\n#4A0E1C\", \"Midnight\\n#0D1033\", \"Forest\\n#0F3B2E\", \"Aubergine\\n#2B0F2E\", \"Brass\\n#C19A4B\", \"Bone\\n#EFE6D8\" in each swatch, at the bottom left, 20 in.\nMake the swatch-labels readable, bone or ink.\n\n-- 02 type\nWrite \"02  TYPE\" called h-type as a heading, under the swatches, 110 apart.\nWrite \"Aa\" called aa-display in Bodoni Moda italic, size 190, under the h-type, 40 apart.\nWrite \"Aa\" called aa-body in Jost, size 190, beside the aa-display, 300 apart.\nWrite \"Aa\" called aa-mono in Martian Mono, size 150, beside the aa-body, 300 apart.\nMake the aa-display and the aa-body bone.\nMake the aa-mono brass.\nWrite \"Bodoni Moda\\nDisplay · headlines\", \"Jost\\nBody · interface\", \"Martian Mono\\nCode · labels · data\" as a note, called type-note, under the aa-display, the aa-body and the aa-mono, 30 apart.\n\n-- 03 imagery\nWrite \"03  IMAGERY\" called h-image as a heading, under the type-notes, 100 apart.\nLet there be 3 rectangles called img, 440 by 380, corners 28, in a row, 460 apart, under the h-image, 40 apart.\nPrint @hallows.jpg in the first img, focused at 0.3 0.4.\nPrint @sienna-shoreline.jpg in the second img, duotone #0d1033 and #efe6d8, focused at 0.5 0.45.\nPrint @tiara-night.jpg in the third img, grayscale, contrast 1.2, focused at 0.5 0.25.\nGive the imgs a shadow, 18 down, blur 40, 60% opacity.\n\nWrite \"Low light. Warm skin. One colour leads.\" called rule, size 30, under the imgs, 50 apart.\nWrite \"studiomorgana.xyz\" called url in Martian Mono, size 24, under the third img, 50 apart, lined up on the right.\nMake the rule bone.\nMake the url brass.\n```","core":false},{"id":"example:a-music-player-skin-lit","title":"Example: A music player skin: lit metal, chrome, a table, everything placed in or beside its panel (it was given @hallows.jpg)","about":"A music player skin: lit metal, chrome, a table, everything placed in or beside its panel (it was given @hallows.jpg)","text":"## A music player skin: lit metal, chrome, a table, everything placed in or beside its panel (it was given @hallows.jpg)\n```gt\n-- A 2005 music player skin: brushed aluminium, a glowing green LCD, chrome transport buttons, an aqua play button,\n-- glossy window lights, a striped playlist. Lit, not flat: the metal catches the light as the piece tilts.\n-- Laid out with words: the panels are placed, everything inside them is put in, under or beside them.\nLet there be a canvas called player-skin, 1600 by 1000, from aluminium.\nBrush the card at 0 degrees.\nLet text be in Jost, size 24.\nLet an lcd-text be in Martian Mono, size 22, aligned left, #27331a.\n\n-- the window\nLet there be a rectangle called body, 1520 by 920, corners 34, at 800 500.\nMake the body #d9dce1.\nGive the body an outline in #8d939c, 3 wide.\nLet there be a rectangle called titlebar, 1520 by 70, corners 34, in the body, at the top.\nMake the titlebar a gradient from #f4f5f7 to #b9bec6, angled 90.\nWrite \"Morgana Player\" called title in Jost bold, size 30, in the titlebar.\nMake the title #3a3f47.\nGive the title a shadow, 1 down, blur 0, in #ffffff, 90% opacity.\n\n-- window lights\nLet there be 3 circles called light, 13 big, in a row, 36 apart, in the titlebar, at the left, 30 in.\nMake the first light a radial gradient from #ff8a80 to #c62828.\nMake the second light a radial gradient from #ffe082 to #f9a825.\nMake the third light a radial gradient from #a5d6a7 to #2e7d32.\nGive the lights an outline in #00000055, 1 wide.\nGive the lights an inner shadow, 3 up, blur 4, in #ffffff, 60% opacity.\n\n-- the LCD\nLet there be a rectangle called lcd, 760 by 210, corners 18, at 800 245.\nMake the lcd a gradient from #d8e8b8 to #a9c47f, angled 90.\nGive the lcd an inner shadow, 6 down, blur 14, 55% opacity.\nGive the lcd an outline in #6d7a5a, 2 wide.\nWrite \"LANTERNS\" called song as an lcd-text, size 42, tracking 4, in the lcd, at the top left, 30 in.\nWrite \"Vesper Lane — Ember Season\" called artist as an lcd-text, under the song, 14 apart.\nLet there be a rectangle called track, 520 by 10, corners 5, in the lcd, at the bottom, 34 in.\nLet there be a rectangle called played, 340 by 10, corners 5, in the track, at the left.\nWrite \"2:41\" called elapsed as an lcd-text, left of the track, 16 apart.\nWrite \"-1:26\" called remaining as an lcd-text, beside the track, 16 apart.\nMake the track #27331a, 80% see-through.\nMake the played #27331a.\nLet there be 8 rectangles called eq, 10 by 44, in a row, 16 apart, in the lcd, at the top right, 30 in.\nMake the eqs #27331a, 25% see-through.\nMake every other eq #27331a.\n\n-- album art, to the left of the LCD\nLet there be a rectangle called art, 200 by 200, corners 10, left of the lcd, 80 apart.\nPrint @hallows.jpg in the art, focused at 0.33 0.42.\nGive the art a shadow, 8 down, blur 18, 50% opacity.\nGive the art an outline in #ffffff, 3 wide.\n\n-- transport: chrome buttons, aqua play, to the right of the LCD\nLet there be a circle called play, 62 big, beside the lcd, 105 apart.\nLet there be a circle called prev, 46 big, left of the play, 6 apart.\nLet there be a circle called next, 46 big, beside the play, 6 apart.\nMake the prev and the next mirror chrome.\nEmboss the prev, 0.25 mm high, soft 0.6.\nEmboss the next, 0.25 mm high, soft 0.6.\nMake the play a radial gradient from #a7dcff to #1565c0.\nGive the play an outline in #0d3c78, 2 wide.\nEmboss the play, 0.35 mm high, soft 0.5.\nSpray the play with gloss, 40 µm thick.\nLet there be a triangle called play-icon, 22 big, pointing right, in the play.\nLet there be a triangle called prev-icon, 13 big, pointing left, in the prev.\nLet there be a triangle called next-icon, 13 big, pointing right, in the next.\nMake the play-icon #ffffff.\nMake the prev-icon and the next-icon #3a3f47.\n\n-- volume, under the buttons\nLet there be a rectangle called groove, 300 by 10, corners 5, under the play, 34 apart.\nDeboss the groove, 0.06 mm deep.\nMake the groove #8d939c.\nLet there be a circle called knob, 17 big, in the groove, at the right, 60 in.\nMake the knob mirror chrome.\nEmboss the knob, 0.3 mm high, soft 0.5.\n\n-- the playlist\nLet there be a rectangle called list, 1440 by 470, corners 14, at 800 655.\nMake the list #ffffff.\nGive the list an inner shadow, 3 down, blur 8, 40% opacity.\nLet there be a table called playlist, 1436 by 448, at 800 650, 8 rows, columns at 28, 78, 818 and 1398 right, in Jost, size 24.\nWrite \"1\", \"Lanterns\", \"Vesper Lane\", \"4:07\" in the next row of the playlist.\nWrite \"2\", \"Hollow\", \"Vesper Lane\", \"3:52\" in the next row of the playlist.\nWrite \"3\", \"Ember Season\", \"Vesper Lane\", \"5:10\" in the next row of the playlist.\nWrite \"4\", \"Paper Moon\", \"Vesper Lane\", \"3:38\" in the next row of the playlist.\nWrite \"5\", \"Candle Hour\", \"Vesper Lane\", \"4:21\" in the next row of the playlist.\nWrite \"6\", \"Late October\", \"Vesper Lane\", \"2:59\" in the next row of the playlist.\nMake every other playlist-row #edf3fb.\nMake the third playlist-row a gradient from #4a90e2 to #2a6fc4, angled 90.\nMake the playlist-words #2b3036.\nMake the third playlist-words white.\n\n-- status bar\nWrite \"6 songs · 24.1 minutes · 58.3 MB\" called status, size 22, under the list, 20 apart.\nMake the status #5b616a.\n```","core":false},{"id":"example:a-video-with-events-move","title":"Example: A video with events: move, change and when","about":"A video with events: move, change and when","text":"## A video with events: move, change and when\n```gt\n-- Events in plain English: each sentence happens when the one before it has finished.\nLet there be a flat video called events, 1080 by 1080, on #14121a, 5 s long.\nLet there be a card called ball, of cardstock, 200 by 200, round, at 200 300.\nLet there be a card called banner, of cardstock, 820 by 240, corners 40, at 540 760.\nWrite \"It landed\" called word in Lilita One, at 410 150, size 110.\n\nMake the ball a radial gradient from #fff6c9 to #ff7a3d.\nMake the banner a gradient from #3a1c71 to #d76d77 to #ffaf7b, angled 0.\nMake the word white.\n\nWhen the video reaches 0.5 s, move the ball to 880 300 over 1.4 s, bouncing.\nWhen the ball arrives, change the banner to visible over 0.4 s.\nWhen the banner appears, change the ball to 130% size for 0.3 s, then back.\nWhen the banner appears, make the banner pulse, by 0.03, every 1.2 s.\nWhen the video reaches 4.2 s, move the ball 300 down over 0.6 s.\n```","core":false},{"id":"example:a-scene-with-four-objects","title":"Example: A scene with four objects","about":"A scene with four objects","text":"## A scene with four objects\n```gt\n-- First element-model test: the same SUMMONS notice on three bodies, plus a sprayed card.\ncreate a stage called three-bodies, 1500 by 1100, on #cfc6b4.\n\nmix a paint called leaf from 1 part phthalo blue and 2 parts hansa yellow, satin.\nmix a paint called sunset from 3 parts cadmium red and 1 part hansa yellow and a touch of white, gloss.\n\nmake a paper called memo from bond, 420 by 560, at 260 560, turned -4, torn top edge, aged 0.3.\nwrite \"SUMMONS\" called memo-title in Big Shoulders Display, at 210 110, size 64.\nwrite \"to report for duty\" called memo-line in Lora, at 210 170, size 26.\ndraw a circle called memo-seal, 54 big, at 210 360.\nenamel the memo-title and the memo-line in #222018.\nenamel the memo-seal in #a3221b.\n\nmake a card called ticket from cardstock, 420 by 560, at 740 560, turned 2.\nwrite \"SUMMONS\" called ticket-title in Big Shoulders Display, at 210 110, size 64.\nwrite \"to report for duty\" called ticket-line in Lora, at 210 170, size 26.\ndraw a circle called ticket-seal, 54 big, at 210 360.\nenamel the ticket-title and the ticket-line in #222018.\nemboss the ticket-seal, 0.15 mm high.\nfoil the ticket-seal with gold.\n\nmake a plate called plaque from stainless, 420 by 560, at 1220 560, turned -1.\nwrite \"SUMMONS\" called plaque-title in Big Shoulders Display, at 210 110, size 64.\nwrite \"to report for duty\" called plaque-line in Lora, at 210 170, size 26.\ndraw a circle called plaque-seal, 54 big, at 210 360.\nengrave the plaque-title and the plaque-line, 0.06 mm deep.\ninlay the plaque-title and the plaque-line with #1c1c20, 0.02 mm deep.\nemboss the plaque-seal, 0.2 mm high.\nplate the plaque-seal with gold.\n\nmake a card called swatch from black-card, 300 by 300, at 980 940, turned 8, 3 mm up.\ndraw a star called swatch-star, 5 points, 110 big, 46 inner, at 150 150.\nspray the swatch with sunset, medium nozzle, 25 cm away, 2 passes, sweeping left to right.\nspray the swatch-star with leaf, fine nozzle, 10 cm away, 3 passes, soft edges.\nsend the swatch behind the plaque.\n```","core":false},{"id":"example:a-video-a-card-sprayed","title":"Example: A video: a card sprayed coat by coat","about":"A video: a card sprayed coat by coat","text":"## A video: a card sprayed coat by coat\n```gt\n-- Graffiti fancard, painted live: an original street piece sprayed onto a stainless card, coat by coat.\ncreate a video called graffiti, 1080 by 1350, on #17171a, 10 s long.\n\nmix a paint called magenta from 3 parts quinacridone magenta and a touch of titanium white, gloss.\nmix a paint called teal from 2 parts phthalo blue and 1 part phthalo green and 1 part titanium white, gloss.\nmix a paint called sun from 3 parts cadmium yellow and a touch of titanium white, gloss.\nmix a paint called ink from 1 part carbon black, satin.\nmix a paint called chalk from 1 part titanium white, satin.\nmix a paint called flame from 2 parts cadmium orange and 1 part cadmium red, gloss.\n\nmake a plate called card from stainless, 816 by 1284, at 540 675, turned -2, 1 mm up.\nwrite \"WILD\" called tag in Sedgwick Ave Display, at 408 624, size 360.\nwrite \"STYLE\" called tag-low in Sedgwick Ave Display, at 432 828, size 228.\ndraw a star called spark-1, 4 points, 55 big, 12 inner, at 672 360.\ndraw a star called spark-2, 4 points, 34 big, 7 inner, at 154 948.\ndraw a star called spark-3, 4 points, 26 big, 6 inner, at 708 912.\ndraw a shape called crown, from 252 396 to 300 300 to 360 372 to 408 276 to 456 372 to 516 300 to 564 396.\ndraw a rectangle called flame-band, 816 by 108, at 408 702.\ndraw a rectangle called flame-band-low, 816 by 72, at 408 870.\nwrite \"fancard · spray series · 001\" called caption in Permanent Marker, at 408 1200, size 40.\n\nspray the card with magenta, medium nozzle, 35 cm away, 2 passes, sweeping from the top left, at 0.6 s, for 1.4 s.\nspray the card with teal, medium nozzle, 35 cm away, 2 passes, sweeping from the bottom right, at 1.6 s, for 1.4 s.\nspray the tag grown by 16 and the tag-low grown by 16 with ink, fine nozzle, 8 cm away, 2 passes, at 3 s, for 1.2 s, with drips.\nspray the tag and the tag-low with sun, fine nozzle, 6 cm away, 2 passes, at 4.2 s, for 1.4 s, with drips.\nspray the tag within the flame-band and the tag-low within the flame-band-low with flame, fine nozzle, 6 cm away, 2 passes, at 5.6 s, for 0.8 s.\nspray the crown grown by 5 with chalk, fine nozzle, 5 cm away, 2 passes, at 6.4 s, for 0.6 s, with drips.\nspray the spark-1 and the spark-2 and the spark-3 with chalk, fine nozzle, 4 cm away, 2 passes, at 7 s, for 0.5 s.\nspray the caption with ink, fine nozzle, 4 cm away, 2 passes, at 7.5 s, for 0.6 s.\nspray the card with gloss, 40 µm thick.\n```","core":false},{"id":"example:a-video-explainer-with-reveals","title":"Example: A video explainer with reveals, captions and exits","about":"A video explainer with reveals, captions and exits","text":"## A video explainer with reveals, captions and exits\n```gt\n-- Mean reversion, explained in 24 seconds. A 9:16 motion piece built only from godtongue elements on a desk.\ncreate a video called mean-reversion, 1080 by 1920, on #d9d1c2, 24 s long.\n\n-- 1 · title\nmake a paper called title from bond, 900 by 520, at 540 820.\nwrite \"MEAN REVERSION\" called title-head in Bodoni Moda, at 450 235, size 92.\ndraw a line called title-rule from 300 285 to 600 285, 3 wide.\nwrite \"a quant strategy, explained\" called title-sub in Jost, at 450 350, size 40.\nwrite \"QUANT NOTES · 01\" called title-tag in Martian Mono, at 450 440, size 22.\nenamel the title-head and the title-rule and the title-sub in #1d1b18.\nenamel the title-tag in #c8361f.\n\n-- 2 · the chart\nmake a paper called chart from bond, 960 by 860, at 540 820.\nwrite \"PRICE  vs  20-DAY MEAN\" called chart-head in Martian Mono, at 480 90, size 26.\ndraw a line called grid-1 from 90 200 to 890 200, 2 wide.\ndraw a line called grid-2 from 90 320 to 890 320, 2 wide.\ndraw a line called grid-3 from 90 440 to 890 440, 2 wide.\ndraw a line called grid-4 from 90 560 to 890 560, 2 wide.\ndraw a line called grid-5 from 90 680 to 890 680, 2 wide.\ndraw a curve called upper from 90 316 through 164 310 through 239 305 through 313 301 through 388 298 through 462 296 through 537 296 through 611 298 through 685 301 through 760 306 through 834 311 to 890 315, 3 wide.\ndraw a curve called lower from 90 564 through 164 558 through 239 553 through 313 549 through 388 546 through 462 544 through 537 544 through 611 546 through 685 549 through 760 554 through 834 559 to 890 563, 3 wide.\ndash the upper, 14 on 10 off.\ndash the lower, 14 on 10 off.\ndraw a curve called mean from 90 440 through 164 434 through 239 429 through 313 425 through 388 422 through 462 420 through 537 420 through 611 422 through 685 425 through 760 430 through 834 435 to 890 439, 4 wide.\ndraw a curve called price from 90 356 through 109 384 through 127 424 through 146 428 through 164 446 through 183 452 through 202 441 through 220 444 through 239 419 through 257 441 through 276 431 through 295 472 through 313 454 through 332 458 through 350 434 through 369 444 through 388 440 through 406 444 through 425 441 through 443 439 through 462 418 through 481 413 through 499 394 through 518 330 through 537 293 through 555 315 through 574 322 through 592 354 through 611 391 through 630 433 through 648 461 through 667 443 through 685 450 through 704 482 through 723 535 through 741 563 through 760 573 through 778 557 through 797 536 through 816 516 through 834 469 through 853 436 through 871 479 to 890 425, 6 wide.\nwrite \"+2σ\" called up-label in Martian Mono, at 925 302, size 24.\nwrite \"μ\" called mean-label in Martian Mono, at 925 428, size 26.\nwrite \"−2σ\" called lo-label in Martian Mono, at 925 562, size 24.\ndraw a circle called exit-ring, 26 big, at 630 433.\nhollow the exit-ring, 5 wide.\nwrite \"EXIT\" called exit-word in Martian Mono, at 630 390, size 24.\nwrite \"time →\" called axis in Martian Mono, at 150 760, size 22.\nenamel the grid-1 and the grid-2 and the grid-3 and the grid-4 and the grid-5 in #e3dccd.\nenamel the upper and the lower and the up-label and the lo-label in #9b8f7e.\nenamel the mean and the mean-label in #1d1b18.\nenamel the price in #1f3b9b.\nenamel the exit-ring and the exit-word in #2c7a3f.\nenamel the chart-head and the axis in #5a5248.\n\n-- 3 · the rule\nmake a card called formula from cardstock, 900 by 220, at 540 1380.\nwrite \"z = (price − mean) ÷ σ\" called z-line in Martian Mono, at 450 100, size 46.\nwrite \"trade only when the stretch is extreme: |z| > 2\" called z-rule in Jost, at 450 165, size 30.\nenamel the z-line in #1d1b18.\nenamel the z-rule in #c8361f.\n\n-- 4 · stamps\nmake a sticker called sell-stamp from ink, 300 by 140, at 760 590, turned -9.\ndraw a rectangle called sell-box, 280 by 120, at 150 70, corners 14.\nhollow the sell-box, 8 wide.\nwrite \"SELL\" called sell-word in Big Shoulders Display, at 150 100, size 92.\nenamel the sell-box and the sell-word in #c8361f.\n\nmake a sticker called buy-stamp from ink, 300 by 140, at 640 1100, turned 7.\ndraw a rectangle called buy-box, 280 by 120, at 150 70, corners 14.\nhollow the buy-box, 8 wide.\nwrite \"BUY\" called buy-word in Big Shoulders Display, at 150 100, size 92.\nenamel the buy-box and the buy-word in #2c7a3f.\n\n-- 5 · the catch\nmake a paper called catch from kraft, 900 by 900, at 540 860.\nwrite \"THE CATCH\" called catch-head in Bodoni Moda, at 450 150, size 84.\ndraw a line called c-up from 90 380 to 810 380, 3 wide.\ndraw a line called c-mean from 90 500 to 810 500, 4 wide.\ndraw a line called c-lo from 90 620 to 810 620, 3 wide.\ndash the c-up, 14 on 10 off.\ndash the c-lo, 14 on 10 off.\ndraw a curve called breakout from 90 510 through 220 470 through 330 520 through 440 440 through 540 380 through 640 300 through 740 250 to 810 200, 6 wide.\nwrite \"a trend is a mean that moved\" called catch-line in Jost, at 450 780, size 38.\nenamel the c-up and the c-lo in #7a5f3e.\nenamel the c-mean and the catch-head and the catch-line in #1d1b18.\nenamel the breakout in #8f1d14.\n\nmake a sticker called stop-stamp from ink, 420 by 140, at 560 1330, turned -5.\ndraw a rectangle called stop-box, 400 by 120, at 210 70, corners 14.\nhollow the stop-box, 8 wide.\nwrite \"STOP-LOSS\" called stop-word in Big Shoulders Display, at 210 100, size 88.\nenamel the stop-box and the stop-word in #c8361f.\n\n-- 6 · end\nmake a card called end from cardstock, 900 by 620, at 540 880.\nwrite \"mean reversion\" called end-head in Bodoni Moda, at 450 250, size 86.\nwrite \"z-score  ·  bands  ·  discipline\" called end-sub in Jost, at 450 345, size 38.\nwrite \"QUANT NOTES · 01\" called end-tag in Martian Mono, at 450 470, size 24.\nenamel the end-head and the end-sub in #1d1b18.\nenamel the end-tag in #c8361f.\n\n-- motion\nbring in the title at 0.2 s, from the bottom.\nremove the title at 3.2 s, to the top.\nbring in the chart at 3.4 s, from the right.\nreveal the grid-1 and the grid-2 and the grid-3 and the grid-4 and the grid-5 at 3.9 s, over 0.5 s, fading.\nreveal the mean and the mean-label at 4.3 s, over 1.4 s, from the left.\nreveal the price at 4.8 s, over 2.6 s, from the left.\nreveal the upper and the lower and the up-label and the lo-label at 7 s, over 0.8 s, fading.\nbring in the formula at 7.6 s, from the bottom.\nreveal the z-rule at 8.6 s, over 0.9 s, from the left.\nglide the camera to 700 760, zoom 1.12, at 9.7 s, over 0.5 s.\nslam the sell-stamp in at 10.1 s.\nglide the camera to 680 1000, zoom 1.2, at 10.9 s, over 0.6 s.\nslam the buy-stamp in at 11.6 s.\nglide the camera to 540 960, zoom 1, at 12.6 s, over 0.6 s.\nreveal the exit-ring and the exit-word at 13.3 s, over 0.4 s, fading.\nremove the chart at 16.2 s, to the left.\nremove the sell-stamp at 16.2 s, to the left.\nremove the buy-stamp at 16.2 s, to the left.\nremove the formula at 9.4 s, to the bottom.\nbring in the catch at 16.5 s, from the right.\nreveal the c-up and the c-mean and the c-lo at 17.1 s, over 0.5 s, fading.\nreveal the breakout at 17.5 s, over 1.8 s, from the left.\nreveal the catch-line at 19.4 s, over 0.8 s, from the left.\nslam the stop-stamp in at 19.9 s.\nremove the catch at 21.2 s, to the left.\nremove the stop-stamp at 21.2 s, to the left.\nbring in the end at 21.4 s, from the bottom.\n\n-- captions\nstyle the captions in Jost, size 62, #1d1b18, at 1640.\ncaption \"Mean reversion: the bet that stretched prices snap back.\" at 0.4 s, for 2.8 s, \"snap back\" in #c8361f.\ncaption \"Start with a rolling average of the price.\" at 3.8 s, for 3 s, \"rolling average\" in #c8361f.\ncaption \"Then measure how far price strays, in standard deviations.\" at 7 s, for 2.6 s, \"standard deviations\" in #c8361f.\ncaption \"Two sigma above the mean? Sell.\" at 9.9 s, for 1.6 s, \"Sell\" in #c8361f.\ncaption \"Two sigma below? Buy.\" at 11.5 s, for 1.5 s, \"Buy\" in #2c7a3f.\ncaption \"Close the trade when price is back at the mean.\" at 13.1 s, for 3 s, \"back at the mean\" in #2c7a3f.\ncaption \"The catch: a trend can keep going. Size small, and cut losses.\" at 16.8 s, for 4.3 s, \"cut losses\" in #c8361f.\ncaption \"Simple to state. Hard to trade well.\" at 21.7 s, for 2.2 s, \"Hard\" in #c8361f.\n```","core":false}];
